export interface Users {
  /**
   * Compte d'appartenance ; NULL pour les administrateurs (hors compte client)
   */
  account_id: string | null;
  activated_at: Timestamp | null;
  created_at: Generated<Timestamp>;
  deletion_requested_at: Timestamp | null;
  /**
   * Identifiant de ce profil chez Digitorn, facultatif (inutile pour un agent appelé par API directe, hypothèse H11)
   */
  digitorn_user_ref: string | null;
  /**
   * Email de connexion, unique et insensible à la casse. Pour un invité actif, sa modification change aussi l'email de connexion (US-19 RF4)
   */
  email: string;
  failed_login_count: Generated<number>;
  first_name: string;
  /**
   * core = invité 1 (premier invité ajouté, ou désigné par l'utilisateur principal) ; secondary = invités 2 à n (D1, D6)
   */
  guest_rank: GuestRank | null;
  id: Generated<string>;
  /**
   * Étape de la configuration initiale (utilisateur principal) pour reprendre là où il s'est arrêté ; NULL pour invités et admins
   */
  initial_setup_step: InitialSetupStep | null;
  last_name: string;
  /**
   * Fin du blocage de 15 min après 5 échecs consécutifs de mot de passe (US-3 RF4)
   */
  login_locked_until: Timestamp | null;
  password_hash: string | null;
  /**
   * Téléphone mobile pour SMS (invitation, code de vérification). Distinct du téléphone saisi pour les agents (US-19 RF5)
   */
  phone: string | null;
  /**
   * Date de suppression définitive des données du profil : délai de grâce de 30 jours (auto-suppression, durée unique décidée le 01/10/2026) ou X jours après retrait (US-20 RT2, paramètre de la console)
   */
  purge_scheduled_at: Timestamp | null;
  removed_at: Timestamp | null;
  role: UserRole;
  /**
   * pending_activation = invitation/activation en attente ; active ; grace_period = suppression demandée par le profil ; removed = invité retiré, données purgées après X jours
   */
  status: Generated<UserStatus>;
  updated_at: Generated<Timestamp>;
}

